"""Business logic services."""
from datetime import datetime, timedelta
from typing import Optional

from sqlalchemy.orm import Session

from src.backend.database import Account, Budget, Debt, Transaction, TransactionCategory
from src.backend.schemas import (
    MonthlyBudgetSummary,
    WeeklyBudgetSummary,
)


class AccountService:
    """Account management service."""

    @staticmethod
    def get_all_accounts(db: Session) -> list[Account]:
        """Get all accounts."""
        return db.query(Account).all()

    @staticmethod
    def get_account(db: Session, account_id: int) -> Optional[Account]:
        """Get account by ID."""
        return db.query(Account).filter(Account.id == account_id).first()

    @staticmethod
    def create_account(db: Session, name: str, account_type: str, balance: float = 0.0) -> Account:
        """Create a new account."""
        account = Account(name=name, account_type=account_type, balance=balance)
        db.add(account)
        db.commit()
        db.refresh(account)
        return account

    @staticmethod
    def update_account_balance(db: Session, account_id: int, balance: float) -> Optional[Account]:
        """Update account balance."""
        account = db.query(Account).filter(Account.id == account_id).first()
        if account:
            account.balance = balance
            account.updated_at = datetime.utcnow()
            db.commit()
            db.refresh(account)
        return account

    @staticmethod
    def get_total_balance(db: Session) -> float:
        """Get total balance across all accounts."""
        accounts = db.query(Account).all()
        return sum(acc.balance for acc in accounts)


class TransactionService:
    """Transaction management service."""

    @staticmethod
    def create_transaction(
        db: Session,
        account_id: int,
        amount: float,
        category: TransactionCategory,
        description: str,
        date: Optional[datetime] = None,
    ) -> Transaction:
        """Create a new transaction."""
        transaction = Transaction(
            account_id=account_id,
            amount=amount,
            category=category,
            description=description,
            date=date or datetime.utcnow(),
        )
        db.add(transaction)

        # Update account balance
        account = db.query(Account).filter(Account.id == account_id).first()
        if account:
            if category == TransactionCategory.INCOME:
                account.balance += amount
            else:
                account.balance -= amount
            account.updated_at = datetime.utcnow()

        db.commit()
        db.refresh(transaction)
        return transaction

    @staticmethod
    def get_all_transactions(db: Session) -> list[Transaction]:
        """Get all transactions."""
        return db.query(Transaction).order_by(Transaction.date.desc()).all()

    @staticmethod
    def get_account_transactions(db: Session, account_id: int) -> list[Transaction]:
        """Get transactions for an account."""
        return (
            db.query(Transaction)
            .filter(Transaction.account_id == account_id)
            .order_by(Transaction.date.desc())
            .all()
        )

    @staticmethod
    def get_transactions_by_month(db: Session, year: int, month: int) -> list[Transaction]:
        """Get transactions for a specific month."""
        start_date = datetime(year, month, 1)
        if month == 12:
            end_date = datetime(year + 1, 1, 1)
        else:
            end_date = datetime(year, month + 1, 1)

        return (
            db.query(Transaction)
            .filter(Transaction.date >= start_date, Transaction.date < end_date)
            .order_by(Transaction.date.desc())
            .all()
        )

    @staticmethod
    def get_transactions_by_week(db: Session, week_start: datetime) -> list[Transaction]:
        """Get transactions for a specific week."""
        week_end = week_start + timedelta(days=7)
        return (
            db.query(Transaction)
            .filter(Transaction.date >= week_start, Transaction.date < week_end)
            .order_by(Transaction.date.desc())
            .all()
        )


class BudgetService:
    """Budget management service."""

    @staticmethod
    def create_budget(
        db: Session, category: TransactionCategory, monthly_limit: float
    ) -> Budget:
        """Create a new budget."""
        budget = Budget(category=category, monthly_limit=monthly_limit)
        db.add(budget)
        db.commit()
        db.refresh(budget)
        return budget

    @staticmethod
    def get_budget(db: Session, category: TransactionCategory) -> Optional[Budget]:
        """Get budget by category."""
        return db.query(Budget).filter(Budget.category == category).first()

    @staticmethod
    def get_all_budgets(db: Session) -> list[Budget]:
        """Get all budgets."""
        return db.query(Budget).all()

    @staticmethod
    def update_budget(
        db: Session, category: TransactionCategory, monthly_limit: float
    ) -> Optional[Budget]:
        """Update budget."""
        budget = db.query(Budget).filter(Budget.category == category).first()
        if budget:
            budget.monthly_limit = monthly_limit
            budget.updated_at = datetime.utcnow()
            db.commit()
            db.refresh(budget)
        return budget

    @staticmethod
    def get_monthly_summary(db: Session, year: int, month: int) -> list[MonthlyBudgetSummary]:
        """Get monthly budget summary."""
        budgets = db.query(Budget).all()
        transactions = TransactionService.get_transactions_by_month(db, year, month)

        summary = []
        for budget in budgets:
            spent = sum(
                t.amount for t in transactions if t.category == budget.category
            )
            remaining = budget.monthly_limit - spent
            percentage = (spent / budget.monthly_limit * 100) if budget.monthly_limit > 0 else 0

            summary.append(
                MonthlyBudgetSummary(
                    category=budget.category,
                    spent=spent,
                    limit=budget.monthly_limit,
                    remaining=remaining,
                    percentage=percentage,
                )
            )

        return summary

    @staticmethod
    def get_weekly_summary(db: Session, week_start: datetime) -> WeeklyBudgetSummary:
        """Get weekly budget summary."""
        transactions = TransactionService.get_transactions_by_week(db, week_start)
        week_end = week_start + timedelta(days=6)

        category_totals = {}
        total_spent = 0.0

        for transaction in transactions:
            if transaction.category != TransactionCategory.INCOME:
                category_totals[transaction.category.value] = (
                    category_totals.get(transaction.category.value, 0.0) + transaction.amount
                )
                total_spent += transaction.amount

        return WeeklyBudgetSummary(
            week_start=week_start.strftime("%Y-%m-%d"),
            week_end=week_end.strftime("%Y-%m-%d"),
            total_spent=total_spent,
            categories=category_totals,
        )


class DebtService:
    """Debt tracking service."""

    @staticmethod
    def create_debt(
        db: Session,
        name: str,
        principal: float,
        interest_rate: float,
        monthly_payment: float,
        description: Optional[str] = None,
    ) -> Debt:
        """Create a new debt."""
        debt = Debt(
            name=name,
            principal=principal,
            remaining=principal,
            interest_rate=interest_rate,
            monthly_payment=monthly_payment,
            description=description,
        )
        db.add(debt)
        db.commit()
        db.refresh(debt)
        return debt

    @staticmethod
    def get_all_debts(db: Session) -> list[Debt]:
        """Get all debts."""
        return db.query(Debt).all()

    @staticmethod
    def get_debt(db: Session, debt_id: int) -> Optional[Debt]:
        """Get debt by ID."""
        return db.query(Debt).filter(Debt.id == debt_id).first()

    @staticmethod
    def update_debt_remaining(db: Session, debt_id: int, remaining: float) -> Optional[Debt]:
        """Update remaining debt amount."""
        debt = db.query(Debt).filter(Debt.id == debt_id).first()
        if debt:
            debt.remaining = max(0, remaining)
            debt.updated_at = datetime.utcnow()
            db.commit()
            db.refresh(debt)
        return debt

    @staticmethod
    def update_debt_payment(db: Session, debt_id: int, monthly_payment: float) -> Optional[Debt]:
        """Update monthly payment amount."""
        debt = db.query(Debt).filter(Debt.id == debt_id).first()
        if debt:
            debt.monthly_payment = monthly_payment
            debt.updated_at = datetime.utcnow()
            db.commit()
            db.refresh(debt)
        return debt

    @staticmethod
    def get_total_debt(db: Session) -> float:
        """Get total remaining debt."""
        debts = db.query(Debt).all()
        return sum(debt.remaining for debt in debts)

    @staticmethod
    def get_total_monthly_payments(db: Session) -> float:
        """Get total monthly debt payments."""
        debts = db.query(Debt).all()
        return sum(debt.monthly_payment for debt in debts)

"""FastAPI backend server."""
from contextlib import asynccontextmanager

from fastapi import Depends, FastAPI, HTTPException
from sqlalchemy.orm import Session

from src.backend.database import TransactionCategory, get_db, init_db
from src.backend.schemas import (
    AccountCreate,
    AccountResponse,
    AccountUpdate,
    BudgetCreate,
    BudgetResponse,
    BudgetUpdate,
    DashboardStats,
    DebtCreate,
    DebtResponse,
    DebtUpdate,
    MonthlyBudgetSummary,
    TransactionCreate,
    TransactionResponse,
    WeeklyBudgetSummary,
)
from src.backend.services import (
    AccountService,
    BudgetService,
    DebtService,
    TransactionService,
)


@asynccontextmanager
async def lifespan(app: FastAPI):
    """Initialize database on startup."""
    init_db()
    yield


app = FastAPI(title="Finance TUI API", version="0.1.0", lifespan=lifespan)


# ============================================================================
# Accounts Endpoints
# ============================================================================


@app.get("/api/accounts", response_model=list[AccountResponse])
def get_accounts(db: Session = Depends(get_db)):
    """Get all accounts."""
    return AccountService.get_all_accounts(db)


@app.get("/api/accounts/{account_id}", response_model=AccountResponse)
def get_account(account_id: int, db: Session = Depends(get_db)):
    """Get account by ID."""
    account = AccountService.get_account(db, account_id)
    if not account:
        raise HTTPException(status_code=404, detail="Account not found")
    return account


@app.post("/api/accounts", response_model=AccountResponse)
def create_account(data: AccountCreate, db: Session = Depends(get_db)):
    """Create a new account."""
    try:
        return AccountService.create_account(db, data.name, data.account_type, data.balance)
    except Exception as e:
        raise HTTPException(status_code=400, detail=str(e))


@app.put("/api/accounts/{account_id}", response_model=AccountResponse)
def update_account(account_id: int, data: AccountUpdate, db: Session = Depends(get_db)):
    """Update account balance."""
    account = AccountService.update_account_balance(db, account_id, data.balance)
    if not account:
        raise HTTPException(status_code=404, detail="Account not found")
    return account


# ============================================================================
# Transactions Endpoints
# ============================================================================


@app.get("/api/transactions", response_model=list[TransactionResponse])
def get_transactions(db: Session = Depends(get_db)):
    """Get all transactions."""
    return TransactionService.get_all_transactions(db)


@app.get("/api/accounts/{account_id}/transactions", response_model=list[TransactionResponse])
def get_account_transactions(account_id: int, db: Session = Depends(get_db)):
    """Get transactions for an account."""
    return TransactionService.get_account_transactions(db, account_id)


@app.post("/api/transactions", response_model=TransactionResponse)
def create_transaction(data: TransactionCreate, db: Session = Depends(get_db)):
    """Create a new transaction."""
    account = AccountService.get_account(db, data.account_id)
    if not account:
        raise HTTPException(status_code=404, detail="Account not found")

    try:
        return TransactionService.create_transaction(
            db,
            data.account_id,
            data.amount,
            data.category,
            data.description,
            data.date,
        )
    except Exception as e:
        raise HTTPException(status_code=400, detail=str(e))


# ============================================================================
# Budgets Endpoints
# ============================================================================


@app.get("/api/budgets", response_model=list[BudgetResponse])
def get_budgets(db: Session = Depends(get_db)):
    """Get all budgets."""
    return BudgetService.get_all_budgets(db)


@app.post("/api/budgets", response_model=BudgetResponse)
def create_budget(data: BudgetCreate, db: Session = Depends(get_db)):
    """Create a new budget."""
    existing = BudgetService.get_budget(db, data.category)
    if existing:
        raise HTTPException(status_code=400, detail="Budget for this category already exists")

    try:
        return BudgetService.create_budget(db, data.category, data.monthly_limit)
    except Exception as e:
        raise HTTPException(status_code=400, detail=str(e))


@app.put("/api/budgets/{category}", response_model=BudgetResponse)
def update_budget(category: str, data: BudgetUpdate, db: Session = Depends(get_db)):
    """Update budget."""
    try:
        cat = TransactionCategory(category)
    except ValueError:
        raise HTTPException(status_code=400, detail="Invalid category")

    budget = BudgetService.update_budget(db, cat, data.monthly_limit)
    if not budget:
        raise HTTPException(status_code=404, detail="Budget not found")
    return budget


@app.get("/api/budgets/summary/monthly", response_model=list[MonthlyBudgetSummary])
def get_monthly_summary(year: int, month: int, db: Session = Depends(get_db)):
    """Get monthly budget summary."""
    try:
        return BudgetService.get_monthly_summary(db, year, month)
    except Exception as e:
        raise HTTPException(status_code=400, detail=str(e))


@app.get("/api/budgets/summary/weekly", response_model=WeeklyBudgetSummary)
def get_weekly_summary(week_start: str, db: Session = Depends(get_db)):
    """Get weekly budget summary."""
    try:
        from datetime import datetime
        ws = datetime.fromisoformat(week_start)
        return BudgetService.get_weekly_summary(db, ws)
    except Exception as e:
        raise HTTPException(status_code=400, detail=str(e))


# ============================================================================
# Debts Endpoints
# ============================================================================


@app.get("/api/debts", response_model=list[DebtResponse])
def get_debts(db: Session = Depends(get_db)):
    """Get all debts."""
    debts = DebtService.get_all_debts(db)
    return [DebtResponse.from_orm(d) for d in debts]


@app.get("/api/debts/{debt_id}", response_model=DebtResponse)
def get_debt(debt_id: int, db: Session = Depends(get_db)):
    """Get debt by ID."""
    debt = DebtService.get_debt(db, debt_id)
    if not debt:
        raise HTTPException(status_code=404, detail="Debt not found")
    return DebtResponse.from_orm(debt)


@app.post("/api/debts", response_model=DebtResponse)
def create_debt(data: DebtCreate, db: Session = Depends(get_db)):
    """Create a new debt."""
    try:
        debt = DebtService.create_debt(
            db,
            data.name,
            data.principal,
            data.interest_rate,
            data.monthly_payment,
            data.description,
        )
        return DebtResponse.from_orm(debt)
    except Exception as e:
        raise HTTPException(status_code=400, detail=str(e))


@app.put("/api/debts/{debt_id}", response_model=DebtResponse)
def update_debt(debt_id: int, data: DebtUpdate, db: Session = Depends(get_db)):
    """Update debt."""
    debt = DebtService.get_debt(db, debt_id)
    if not debt:
        raise HTTPException(status_code=404, detail="Debt not found")

    try:
        debt = DebtService.update_debt_remaining(db, debt_id, data.remaining)
        debt = DebtService.update_debt_payment(db, debt_id, data.monthly_payment)
        return DebtResponse.from_orm(debt)
    except Exception as e:
        raise HTTPException(status_code=400, detail=str(e))


# ============================================================================
# Dashboard Endpoints
# ============================================================================


@app.get("/api/dashboard/stats", response_model=DashboardStats)
def get_dashboard_stats(db: Session = Depends(get_db)):
    """Get dashboard statistics."""
    total_balance = AccountService.get_total_balance(db)
    total_debt = DebtService.get_total_debt(db)
    accounts = AccountService.get_all_accounts(db)
    transactions = TransactionService.get_all_transactions(db)

    return DashboardStats(
        total_balance=total_balance,
        total_debt=total_debt,
        net_worth=total_balance - total_debt,
        accounts_count=len(accounts),
        transactions_count=len(transactions),
    )


