║ Transactions:     {s['transactions_count']:>15}   ║
╚════════════════════════════════════════════╝
"""

    def render(self) -> str:
        """Render the widget."""
        return self._render_stats() if self.stats else "Loading..."


class AccountsWidget(Static):
    """Accounts display widget."""

    def __init__(self, api_client: APIClient):
